// ── Nightly Metrics Computation ──────────────────────────────
// Items come from the Merge node, which concatenated:
//   - MESSAGE_LEDGER rows (message_id, environment, input_preview, status, processed_at)
//   - ERRORS rows (error_message, error_type, workflow_id, workflow_name, execution_id, last_node, severity, timestamp)
//
// We separate them by checking for known fields and filter for today's rows.

const today = new Date().toISOString().slice(0, 10);

let ledgerRows = [];
let errorRows = [];

for (const item of items) {
  const d = item.json;
  if (d.message_id) {
    ledgerRows.push(d);
  } else if (d.error_message) {
    errorRows.push(d);
  }
}

// Filter for today's rows only
const todayLedger = ledgerRows.filter(r => {
  const dt = r.processed_at ? r.processed_at.slice(0, 10) : '';
  return dt === today;
});

const todayErrors = errorRows.filter(r => {
  const dt = r.timestamp ? r.timestamp.slice(0, 10) : '';
  return dt === today;
});

const processedToday = todayLedger.filter(r => r.status === 'processed').length;
const cachedToday = todayLedger.filter(r => r.status === 'cached').length;
const totalToday = todayLedger.length;
const errorsToday = todayErrors.length;
const distinctErrorTypes = [...new Set(todayErrors.map(r => r.error_type))].length;
const environment = ledgerRows[0]?.environment || errorRows[0]?.environment || 'unknown';

// Produce a single summary row
return [{
  json: {
    date: today,
    total_messages: totalToday,
    processed_today: processedToday,
    cached_today: cachedToday,
    errors_today: errorsToday,
    distinct_error_types: distinctErrorTypes,
    drift_events_today: 0,
    environment: environment,
    computed_at: new Date().toISOString()
  }
}];
